import type { ReferralSmsSettings } from "../referral-sms.ts";

type Sql = { query: <T>(query: string, params: unknown[]) => Promise<T[]> };

export type PocketReferralClub = {
  status: "ok";
  generatedAt: string;
  settings: ReferralSmsSettings | null;
  members: {
    id: string;
    name: string;
    phone: string;
    code: string;
    active: boolean;
    tier: string;
    successful: number;
    total: number;
    rewards: { milestone: number; title: string; status: string }[];
  }[];
  /** Unsent stage messages already generated by the site (read-only here; marking sent stays on the site). */
  outbox: { id: string; phone: string; body: string; referrerId: string }[];
  truncated: boolean;
};

const LIMIT = 2000;
const clip = (v: string | null | undefined, n: number) => String(v ?? "").slice(0, n);
const safeId = (raw: string) => String(raw).replace(/[^A-Za-z0-9_.:-]/g, "_").slice(0, 100) || "x";

/**
 * Read-only snapshot of the owner's referral club for the Pocket app: the same rows the site's
 * club panel shows (members, rewards, unsent outbox, owner-edited SMS settings).
 * Caller MUST have verified the session and the studio-owner role first. Only SELECTs: no DDL,
 * no syncReferralRequest, no outbox marking. Referred friends' phones and request ids are NOT exported.
 */
export async function exportPocketReferrals(sql: Sql): Promise<PocketReferralClub> {
  const config = await sql.query<{
    prize5: string; prize10: string; sms_submitted: string; sms_priced: string; sms_booked: string; sms_prize5: string; sms_prize10: string;
  }>(`select prize5, prize10, sms_submitted, sms_priced, sms_booked, sms_prize5, sms_prize10 from studio_referral_settings where id='main'`, []);
  const members = await sql.query<{ id: string; name: string; phone: string; code: string; active: boolean; tier: string; total: number; successful: number }>(
    `select f.id, f.name, f.phone, f.code, f.active, f.tier,
            count(r.id)::int as total,
            count(r.id) filter (where r.successful)::int as successful
       from studio_referrers f
       left join studio_referrals r on r.referrer_id = f.id
      group by f.id
      order by f.created_at desc
      limit ${LIMIT + 1}`,
    [],
  );
  const rewards = await sql.query<{ referrer_id: string; milestone: number; title: string; status: string }>(
    `select referrer_id, milestone, title, status from studio_referral_rewards`,
    [],
  );
  const outbox = await sql.query<{ id: string; phone: string; body: string; referrer_id: string }>(
    `select id, phone, body, referrer_id from studio_referral_outbox where sent_at is null order by created_at desc limit 20`,
    [],
  );
  const c = config[0];
  return {
    status: "ok",
    generatedAt: new Date().toISOString(),
    settings: c
      ? {
          prize5: clip(c.prize5, 160),
          prize10: clip(c.prize10, 160),
          smsSubmitted: clip(c.sms_submitted, 320),
          smsPriced: clip(c.sms_priced, 320),
          smsBooked: clip(c.sms_booked, 320),
          smsPrize5: clip(c.sms_prize5, 320),
          smsPrize10: clip(c.sms_prize10, 320),
        }
      : null,
    members: members.slice(0, LIMIT).map((row) => ({
      id: safeId(row.id),
      name: clip(row.name, 200),
      phone: clip(row.phone, 40),
      code: clip(row.code, 60),
      active: Boolean(row.active),
      tier: clip(row.tier, 40),
      successful: Number(row.successful) || 0,
      total: Number(row.total) || 0,
      rewards: rewards
        .filter((r) => r.referrer_id === row.id)
        .map((r) => ({ milestone: Number(r.milestone) || 0, title: clip(r.title, 160), status: clip(r.status, 40) })),
    })),
    outbox: outbox.map((row) => ({ id: safeId(row.id), phone: clip(row.phone, 40), body: clip(row.body, 1000), referrerId: safeId(row.referrer_id) })),
    truncated: members.length > LIMIT,
  };
}
